import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { type Catalog, resolveLayered } from "./catalog-layer.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// Generated by scripts/build-tileset-lights.mjs from each tileset's Lighting field.
const CATALOG_PATH = path.resolve(__dirname, "../../data/tileset-lights.json");

let stockLights: Record<string, string> | null = null;

/** The CLight a tileset uses by default (e.g. MonlythEx1 -> "Monlyth"), the game's or the Campaign Mod's; falls back to the tileset id. */
export function getTilesetLight(catalog: Catalog, tilesetId: string): string {
  const stock = (id: string): string | undefined => (stockLights ??= JSON.parse(readFileSync(CATALOG_PATH, "utf8")) as Record<string, string>)[id];
  return resolveLayered(catalog.tilesets, tilesetId, (tileset) => tileset.lighting, stock)?.replaceAll("##id##", tilesetId) ?? tilesetId;
}

/** The light a Mission plays in: its `lighting` override, else its tileset's default. */
export function missionLight(catalog: Catalog, blueprint: { readonly lighting?: string | undefined; readonly tilesetId?: string | undefined }): string {
  return blueprint.lighting ?? getTilesetLight(catalog, blueprint.tilesetId ?? "KorhalCityEx2");
}
